'use strict';
const cableInfo={
 RCA:{title:'RCA ピンケーブル',short:'RCA',text:'中央に1本のピン、外側に金属のリング。アナログ音声はアンバランス・1端子1チャンネルです。赤がR、白がL。ステレオには2本（または赤白の2本組）が必要です。',use:'CDJ → DJミキサーのLINE入力',ends:['rca','rca']},
 XLR:{title:'XLR バランスケーブル',short:'XLR',text:'丸い3ピンのコネクター。通常は出力機材側がメスプラグ、入力機材側がオスプラグです。1本でモノラルのバランス音声を送ります。L/Rは2本必要です。',use:'ミキサー → パワードスピーカー / アンプのライン入力',ends:['xlrf','xlrm']},
 TS:{title:'TS シールドケーブル',short:'TS（シールド）',text:'6.35mmフォーンプラグの絶縁リングが1本。楽器用などのアンバランス・モノラルケーブルです。「シールド」はノイズを抑える構造の呼び名で、端子名ではありません。スピーカー用ケーブルとは別物です。',use:'楽器・ライン音声 / SEND・RETURN',ends:['ts','ts']},
 TRS:{title:'TRS バランスケーブル',short:'TRS',text:'6.35mmフォーンプラグの絶縁リングが2本。バランスのライン音声では1本1チャンネルです。ヘッドホン用のステレオTRSと見た目が同じでも、用途・信号が違います。',use:'BOOTH出力 → モニターのTRS / コンボ入力',ends:['trs','trs']},
 TRS_XLR:{title:'TRS → XLR バランスケーブル',short:'TRS → XLR',text:'出力側は6.35mm TRS、入力側はXLRオス。バランス音声を1チャンネル送ります。GenelecをBOOTH OUTへ接続するときなどに使います。ステレオには2本必要です。',use:'DJミキサーのBOOTH → Genelec',ends:['trs','xlrm']},
 XLR_TRS:{title:'XLR → TRS バランスケーブル',short:'XLR → TRS',text:'出力側はXLRメス、入力側は6.35mm TRS。モノラルのバランス・ライン音声を送ります。',use:'ミキサーのXLR出力 → TRSライン入力',ends:['xlrf','trs']},
 SPDIF:{title:'S/PDIF 同軸デジタルケーブル',short:'S/PDIF 75Ω',text:'見た目はRCAと同じ1ピンですが、75Ωの同軸デジタルケーブルです。1本でステレオ音声を伝送。アナログLINEのRCAとは接続先も信号も異なります。',use:'CDJ DIGITAL OUT → DJミキサー DIGITAL IN',ends:['rca','rca']},
 SPEAKON:{title:'speakON スピコン スピーカーケーブル',short:'speakON NL4',text:'太いロック式コネクターを差し込んで回して固定します。パワーアンプからパッシブスピーカーへ、増幅済みの信号を送ります。このアプリではNL4の1+/1−を使用します。',use:'パワーアンプ → パッシブスピーカー',ends:['speakon','speakon']},
 SPK_TS:{title:'スピーカー用 フォーンケーブル',short:'スピーカー用TS',text:'外見はTSシールドと同じですが、増幅済みのスピーカー信号用です。楽器用シールドで代用しません。',use:'アンプのPHONE出力 → パッシブスピーカー',ends:['ts','ts']},
 AES:{title:'AES/EBU デジタルケーブル',short:'AES/EBU 110Ω',text:'3ピンXLRを使う110Ωのデジタル音声ケーブル。1本でステレオ音声を送ります。アナログXLRケーブル・信号とは別に扱います。',use:'DJM-V10 DIGITAL MASTER → AES/EBU入力',ends:['xlrf','xlrm']},
 HEADPHONE:{title:'ヘッドホンケーブル',short:'PHONES',text:'TRSの先端・リング・スリーブでL/Rと共通線を扱うステレオ音声。バランス・モノラルのラインTRSとは用途が違います。',use:'PHONES出力 → ヘッドホン',ends:['trs','trs']}
};
function cableLabel(type){return cableInfo[type]?.short||type}
function plugSVG(type,x,flip=false){let shape='';if(type==='rj45')shape='<rect x="0" y="34" width="45" height="33" rx="5" fill="#285b52" stroke="#65d4bb"/><path d="M45 31H90V70H45Z M53 30V23H77V30" fill="#c0d4ce" stroke="#eff7ef"/><path d="M56 37V55M61 37V55M66 37V55M71 37V55M76 37V55M81 37V55" stroke="#c5a65b" stroke-width="3"/>'; if(type==='rca')shape='<rect x="0" y="32" width="48" height="35" rx="6" fill="#8d5f39" stroke="#e5bd80"/><rect x="47" y="39" width="23" height="21" fill="#ced2cf"/><rect x="70" y="46" width="24" height="6" rx="2" fill="#e4c58c"/><circle cx="12" cy="49" r="5" fill="#d9c28a"/>';
if(type==='xlrf'||type==='xlrm')shape='<rect x="0" y="27" width="53" height="45" rx="8" fill="#454f50" stroke="#9caaa5"/><ellipse cx="55" cy="49" rx="23" ry="27" fill="#283333" stroke="#cbd9c7" stroke-width="3"/>'+[[48,40],[62,40],[55,57]].map(([a,b])=>`<circle cx="${a}" cy="${b}" r="4" fill="${type==='xlrm'?'#e1d59b':'#090e0c'}" stroke="#a6a998"/>`).join('');
if(type==='mini')shape='<g transform="translate(0,12) scale(.76)"><rect x="0" y="32" width="45" height="35" rx="6" fill="#4d5550" stroke="#e6c291"/><path d="M45 39 H89 L103 49 L89 59 H45Z" fill="#ccd1cb"/><path d="M65 39V59M80 39V59" stroke="#161c18" stroke-width="4"/></g>';
if(type==='ts'||type==='trs')shape='<rect x="0" y="32" width="45" height="35" rx="6" fill="#4d5550" stroke="#a8b69e"/><path d="M45 39 H89 L103 49 L89 59 H45Z" fill="#ccd1cb" stroke="#75857a"/><path d="M80 39V59" stroke="#161c18" stroke-width="4"/>'+(type==='trs'?'<path d="M65 39V59" stroke="#161c18" stroke-width="4"/>':'');
if(type==='speakon')shape='<rect x="0" y="27" width="68" height="46" rx="10" fill="#28303a" stroke="#a6bac2"/><rect x="35" y="26" width="20" height="48" rx="4" fill="#3b7db0"/><ellipse cx="72" cy="50" rx="13" ry="23" fill="#11191d" stroke="#acbdc0"/><path d="M70 32L80 37M70 68L80 63" stroke="#a8c0d0" stroke-width="4"/>';
if(type==='hdmi'||type==='microhdmi'){let scale=type==='microhdmi'?'.65':'1';shape=`<g transform="translate(0,${type==='microhdmi'?17:0}) scale(${scale})"><rect x="0" y="29" width="45" height="43" rx="6" fill="#364e63" stroke="#91caef"/><path d="M45 31 H88 L101 42 V58 L88 70 H45Z" fill="#b1c4cd" stroke="#ecf6f9" stroke-width="2"/><path d="M52 40 H83 L90 46 V54 L83 61 H52Z" fill="#26353f"/><path d="M58 45 H80 M58 51 H80 M58 56 H80" stroke="#d7bb7b" stroke-width="2"/></g>`}
if(type==='bnc')shape='<rect x="0" y="31" width="47" height="40" rx="7" fill="#4c405f" stroke="#cbb9ed"/><rect x="47" y="32" width="38" height="38" rx="4" fill="#b9c5ca" stroke="#eff7ff"/><ellipse cx="85" cy="51" rx="13" ry="20" fill="#3d4750" stroke="#e0e5e9" stroke-width="3"/><rect x="70" y="26" width="12" height="8" rx="2" fill="#b9c5ca"/><rect x="70" y="69" width="12" height="8" rx="2" fill="#b9c5ca"/><circle cx="86" cy="51" r="4" fill="#daba71"/>';
if(type==='usbc'||type==='usba')shape='<rect x="0" y="31" width="48" height="40" rx="7" fill="#314d4b" stroke="#83d9d1"/>'+ (type==='usbc'?'<rect x="48" y="39" width="44" height="23" rx="11" fill="#bdc9ca"/><rect x="61" y="44" width="24" height="12" rx="6" fill="#354b4b"/>':'<rect x="48" y="34" width="44" height="34" fill="#bdc9ca"/><rect x="61" y="41" width="23" height="20" fill="#3b7384"/>');
return `<g transform="translate(${x},0) ${flip?'translate(104,0) scale(-1,1)':''}">${shape}</g>`}
function cableDiagram(type){let i=cableInfo[type]||cableInfo.XLR;return `<svg class="connector-diagram" viewBox="0 0 330 115" role="img" aria-label="${i.title}の端子図"><path d="M26 78 C50 106 137 99 165 72 S265 76 308 79" fill="none" stroke="${typeof colors!=='undefined'?colors[type]||'#a8c98c':'#a8c98c'}" stroke-width="7"/>${plugSVG(i.ends[0],22)}${plugSVG(i.ends[1],203,true)}<text x="25" y="111" fill="#a4b59a" font-size="10">出力機材側</text><text x="235" y="111" fill="#a4b59a" font-size="10">入力機材側</text></svg>`}
function openCableGuide(type){let types=Object.keys(cableInfo).filter(t=>typeof isVideo==='undefined'||!isVideo||['HDMI','HDMI_MICRO','SDI','UVC'].includes(t));let selected=type&&cableInfo[type]?type:typeof isVideo!=='undefined'&&isVideo?'HDMI':'RCA';let d=document.querySelector('#cableguide');d.innerHTML=`<div class="guideheader"><div><small>CABLE FIELD GUIDE</small><h2>ケーブル・端子図鑑</h2></div><button id="closeguide" aria-label="図鑑を閉じる">✕</button></div><div class="guidebody"><div class="guidetabs">${types.map(t=>`<button data-guide="${t}" class="${t===selected?'active':''}">${cableLabel(t)}</button>`).join('')}</div><article id="guidecontent"></article></div>`;function show(t){let i=cableInfo[t];document.querySelector('#guidecontent').innerHTML=cableDiagram(t)+`${t==='TS'||t==='TRS'?`<div class="ringnote">絶縁リング：${t==='TS'?'1本＝TS':'2本＝TRS'}</div>`:''}<h3>${i.title}</h3><p>${i.text}</p><div class="selectionhint">主な用途：${i.use}</div><p class="source">端子の形を示す模式図です。色や外装は製品により異なります。RCA・XLR・TRSのアナログ音声は、L/Rそれぞれに1本必要です。</p><p class="source">${t==='PTZ_LAN'?'<a href="https://canon.jp/biz/product/camera/pro-imaging/remotecam/accessory/rcip100" target="_blank" rel="noreferrer">Canon：対応カメラ・LAN制御規格 ↗</a>':['HDMI','HDMI_MICRO','SDI','UVC'].includes(t)?'<a href="https://www.blackmagicdesign.com/products/microconverters" target="_blank" rel="noreferrer">Blackmagic Design：HDMI / SDI変換器 ↗</a>':'<a href="https://hub.yamaha.com/proaudio/livesound/interconnections-101/" target="_blank" rel="noreferrer">Yamaha：音声ケーブル・接続の解説 ↗</a>'}</p>`;d.querySelectorAll('[data-guide]').forEach(b=>b.classList.toggle('active',b.dataset.guide===t))}show(selected);d.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>show(b.dataset.guide));document.querySelector('#closeguide').onclick=()=>d.close();if(!d.open)d.showModal()}
Object.assign(cableInfo,{
 PTZ_LAN:{title:'PTZ制御用LANケーブル（RJ45）',short:'LAN · PTZ制御',text:'8接点のRJ45コネクター。対応する操作盤とカメラのLAN端子をCAT5e以上のケーブルで接続します。矢印は操作コマンドの方向を表します。RJ45でもRS-422端子はLANではありません。制御方式・IP設定の一致が必要。複数台にはネットワークスイッチが必要です。現在は1対1のIP制御をモデル化し、NDI映像・PoE給電は対象外です。',use:'RC-IP100 / RM-IP500 / AW-RP50N / RM-LP100 → 対応PTZカメラ',ends:['rj45','rj45']},
 MINI:{title:'3.5mm TRS ステレオミニケーブル',short:'3.5mm TRS',text:'先端の絶縁リングが2本の3.5mmプラグ。1本でL/Rの2チャンネルを伝送します。Wireless GO IIなどはマイクレベル出力です。ATEMの3.5mm端子は実機でMIC / LINEを選択。6.35mmバランスTRSとは配線と用途が異なります。',use:'RØDEワイヤレス受信機 → カメラ / ATEM MiniのMIC入力',ends:['mini','mini']},
 USB_AUDIO:{title:'USBデジタル音声ケーブル',short:'USB音声',text:'マイクのUSB-C音声出力からPCのUSBホストへデジタル音声を送ります。データ対応ケーブルが必要。PC側がType A / Cのどちらかは実機で確認してください。HDMIやアナログ音声端子への直接変換はできません。',use:'RØDE USB音声出力 → 配信PC USB MEDIA',ends:['usbc','usba']},
 RCA_TS:{title:'RCA → 6.35mm TS アンバランスケーブル',short:'RCA → TS',text:'RCAのモノラル出力から6.35mm TSまたはコンボ入力へ接続する変換ケーブル。入力をLINEに設定してください。L/Rはそれぞれ別の入力へ1本ずつ接続し、PANを設定。ステレオRCAを1本のバランスTRSへまとめる接続ではありません。',use:'DDJ-FLX4 MASTER RCA → MIC/LINEコンボ入力（LINE設定）',ends:['rca','ts']},
 HDMI:{title:'HDMI Type A ケーブル',short:'HDMI',text:'幅広の台形コネクター。デジタル映像と埋め込み音声を1本で送ります。出力→入力で接続。10m以上などの長距離は光HDMI・アクティブケーブル・SDI変換を含め、実機対応を確認してください。',use:'カメラ / PC → HDMIスイッチャー → モニター',ends:['hdmi','hdmi']},
 HDMI_MICRO:{title:'Micro HDMI Type D → HDMI Type A',short:'Micro HDMI → HDMI',text:'カメラ側は小さなMicro HDMI（Type D）、スイッチャー側は標準HDMI（Type A）。Mini HDMI（Type C）とは形が違います。α6400やGoProのMedia Modに使用。変換器ではなく端子サイズを変えるケーブルです。',use:'α6400 / HERO12＋Media Mod → ATEM Mini',ends:['microhdmi','hdmi']},
 SDI:{title:'SDI 75Ω BNC 同軸ケーブル',short:'SDI / BNC 75Ω',text:'丸いBNCコネクターを差し込み、ひねってロックします。75Ωの映像用同軸ケーブル。3Gは主に1080p60まで、12Gは2160p60までの対応ケーブルと機材が必要。HDMIとの変換には能動変換器が必要です。',use:'Z150 / SDI変換器 → ATEM SDI / Constellation',ends:['bnc','bnc']},
 UVC:{title:'USB 映像キャプチャー接続',short:'USB映像',text:'スイッチャーやキャプチャーのUSB映像出力をPCのUSBホストへ接続。USB-C、USB 3.0-B等、機材によって形状が違うため実機の端子を確認。充電専用ケーブルでは使えません。V-1HDのUSB制御端子から映像は出ません。',use:'ATEM / VR-4HD / HDMIキャプチャー → 配信PC',ends:['usbc','usba']}
});

Object.assign(cableInfo,{XLR_MIC_TRS:{title:'XLR → TRS マイクケーブル',short:'XLR → TRS（MIC）',text:'XLRメスから6.35mm TRSのバランス・マイク入力へ1本で接続します。TRSでもステレオミニやライン入力とは信号レベルが異なります。PE-W50CDBの有線マイク入力に使用。ファンタム電源の要否と端子の配線は実機で確認してください。',use:'有線XLRマイク → JVC PE-W50CDBのMIC入力',ends:['xlrf','trs']}});
